            name="home-circle"
            color="#ffffff"
            size={35}
            underlayColor="transparent"
            containerStyle={{
              width: 50,
              marginTop: 5,
              marginLeft: 5,
              marginRight: 5,
            }}
          />
          <Text style={styles.titleMenu}>Inicio</Text>
        </TouchableOpacity>
        <TouchableOpacity
